import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function intOf(v: unknown): number | null {
  if (typeof v === 'number' && Number.isInteger(v)) {
    return v;
  }
  if (typeof v === 'string' && /^-?\d+$/.test(v.trim())) {
    return Number(v.trim());
  }
  return null;
}

function amountOf(v: unknown): string | null {
  if (typeof v === 'number' && Number.isFinite(v)) {
    return String(v);
  }
  if (typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v.trim())) {
    return v.trim();
  }
  return null;
}

function idOf(v: unknown): number {
  const n = intOf(v);
  if (n === null || n <= 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '식별자 형식이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr00604Controller {
  @Get('/account-carryovers')
  async listAccountCarryovers(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const fiscalYear = intOf(q['fiscalYear']);
    if (fiscalYear === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '회계연도를 입력해 주세요.');
    }
    let page = 0;
    if (q['page'] !== undefined && q['page'] !== '') {
      const p = intOf(q['page']);
      if (p === null || p < 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
      }
      page = p;
    }
    let size = DEFAULT_SIZE;
    if (q['size'] !== undefined && q['size'] !== '') {
      const s = intOf(q['size']);
      if (s === null || s < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
      }
      size = Math.min(s, MAX_SIZE);
    }
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT account_carryover_id AS "accountCarryoverId", fiscal_year AS "fiscalYear", ' +
          'account_subject_id AS "accountSubjectId", partner_id AS "partnerId", ' +
          'carryover_amount AS "carryoverAmount", closing_status AS "closingStatus" ' +
          'FROM account_carryover WHERE fiscal_year = CAST(:fiscalYear AS integer) ' +
          'ORDER BY account_carryover_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { fiscalYear, size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM account_carryover WHERE fiscal_year = CAST(:fiscalYear AS integer)',
        { fiscalYear },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/account-carryovers')
  @HttpCode(200)
  async createAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const fiscalYear = intOf(data['fiscalYear']);
    const accountSubjectId = intOf(data['accountSubjectId']);
    const amount = amountOf(data['carryoverAmount']);
    const hasPartner = data['partnerId'] !== undefined && data['partnerId'] !== null && data['partnerId'] !== '';
    const partnerId = hasPartner ? intOf(data['partnerId']) : null;
    if (fiscalYear === null || accountSubjectId === null || amount === null || (hasPartner && partnerId === null)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '회계연도, 계정과목, 이월 금액을 올바르게 입력해 주세요.');
    }
    return transaction(async (db) => {
      await this.ensureSubject(db, accountSubjectId);
      await this.ensurePartner(db, partnerId);
      const rows = await db.query(
        'INSERT INTO account_carryover (fiscal_year, account_subject_id, partner_id, carryover_amount, closing_status, created_at, updated_at) ' +
          'VALUES (CAST(:fiscalYear AS integer), CAST(:accountSubjectId AS bigint), CAST(:partnerId AS bigint), CAST(:amount AS numeric), \'미마감\', now(), now()) ' +
          'RETURNING account_carryover_id AS "accountCarryoverId"',
        { fiscalYear, accountSubjectId, partnerId, amount },
      );
      return rows[0];
    });
  }

  @Put('/account-carryovers/:accountCarryoverId')
  async updateAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['accountCarryoverId']);
    const data = checks.inputOf(req.body);
    const accountSubjectId = intOf(data['accountSubjectId']);
    const amount = amountOf(data['carryoverAmount']);
    const hasPartner = data['partnerId'] !== undefined && data['partnerId'] !== null && data['partnerId'] !== '';
    const partnerId = hasPartner ? intOf(data['partnerId']) : null;
    if (accountSubjectId === null || amount === null || (hasPartner && partnerId === null)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정과목과 이월 금액을 올바르게 입력해 주세요.');
    }
    return transaction(async (db) => {
      const row = await this.findRow(db, id);
      if (row['closingStatus'] === '마감') {
        throw new ApiError(409, 'ACCOUNT_CARRYOVER_CLOSED', '마감된 이월내역입니다. 마감을 취소한 뒤 수정해 주세요.');
      }
      await this.ensureSubject(db, accountSubjectId);
      await this.ensurePartner(db, partnerId);
      await db.execute(
        'UPDATE account_carryover SET account_subject_id = CAST(:accountSubjectId AS bigint), partner_id = CAST(:partnerId AS bigint), ' +
          'carryover_amount = CAST(:amount AS numeric), updated_at = now() WHERE account_carryover_id = CAST(:id AS bigint)',
        { accountSubjectId, partnerId, amount, id },
      );
      return { accountCarryoverId: id };
    });
  }

  @Delete('/account-carryovers/:accountCarryoverId')
  async deleteAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['accountCarryoverId']);
    return transaction(async (db) => {
      const row = await this.findRow(db, id);
      if (row['closingStatus'] === '마감') {
        throw new ApiError(409, 'ACCOUNT_CARRYOVER_CLOSED', '마감된 이월내역입니다. 마감을 취소한 뒤 삭제해 주세요.');
      }
      await db.execute('DELETE FROM account_carryover WHERE account_carryover_id = CAST(:id AS bigint)', { id });
      return {};
    });
  }

  @Post('/account-carryovers/:accountCarryoverId/close')
  @HttpCode(200)
  async closeAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['accountCarryoverId']);
    return transaction(async (db) => {
      const row = await this.findRow(db, id);
      if (row['closingStatus'] !== '미마감') {
        throw new ApiError(409, 'ACCOUNT_CARRYOVER_ALREADY_CLOSED', '이미 마감된 이월내역입니다.');
      }
      await db.execute(
        'UPDATE account_carryover SET closing_status = \'마감\', updated_at = now() WHERE account_carryover_id = CAST(:id AS bigint)',
        { id },
      );
      return { closingStatus: '마감' };
    });
  }

  @Post('/account-carryovers/:accountCarryoverId/cancel-close')
  @HttpCode(200)
  async cancelCloseAccountCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['accountCarryoverId']);
    return transaction(async (db) => {
      const row = await this.findRow(db, id);
      if (row['closingStatus'] !== '마감') {
        throw new ApiError(409, 'ACCOUNT_CARRYOVER_NOT_CLOSED', '마감되지 않은 이월내역입니다.');
      }
      await db.execute(
        'UPDATE account_carryover SET closing_status = \'미마감\', updated_at = now() WHERE account_carryover_id = CAST(:id AS bigint)',
        { id },
      );
      return { closingStatus: '미마감' };
    });
  }

  private async findRow(db: any, id: number) {
    const rows = await db.query(
      'SELECT account_carryover_id AS "accountCarryoverId", closing_status AS "closingStatus" ' +
        'FROM account_carryover WHERE account_carryover_id = CAST(:id AS bigint) FOR UPDATE',
      { id },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'ACCOUNT_CARRYOVER_NOT_FOUND', '대상 이월내역을 찾을 수 없습니다.');
    }
    return rows[0];
  }

  private async ensureSubject(db: any, accountSubjectId: number) {
    const rows = await db.query(
      'SELECT account_subject_id FROM account_subject WHERE account_subject_id = CAST(:accountSubjectId AS bigint)',
      { accountSubjectId },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'ACCOUNT_SUBJECT_NOT_FOUND', '등록되지 않은 계정과목입니다.');
    }
  }

  private async ensurePartner(db: any, partnerId: number | null) {
    if (partnerId === null) {
      return;
    }
    const rows = await db.query(
      'SELECT partner_id FROM partner WHERE partner_id = CAST(:partnerId AS bigint)',
      { partnerId },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'PARTNER_NOT_FOUND', '등록되지 않은 거래처입니다.');
    }
  }
}

