import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Mode =
  | { type: 'create' }
  | { type: 'edit'; row: Row }
  | { type: 'delete'; row: Row }
  | { type: 'close'; row: Row }
  | { type: 'cancel'; row: Row };

const SIZE = 20;

export default function FnSfr00604Page({ role, notify }: PageProps) {
  const thisYear = new Date().getFullYear();
  const [yearInput, setYearInput] = useState<number | string>(thisYear);
  const [year, setYear] = useState<number | string>(thisYear);
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode | null>(null);
  const [subjectId, setSubjectId] = useState<number | string>('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');

  const { data, error, loading, reload } = useData<Page>(
    () => {
      if (year === '') {
        return Promise.resolve({ items: [], page: 0, size: SIZE, total: 0 } as Page);
      }
      return call<Page>('GET', '/account-carryovers', role, undefined, { fiscalYear: year, page, size: SIZE });
    },
    [year, page, role],
  );

  function openCreate() {
    setSubjectId('');
    setPartnerId('');
    setAmount('');
    setMode({ type: 'create' });
  }

  function openEdit(row: Row) {
    setSubjectId(row['accountSubjectId'] as number);
    setPartnerId(row['partnerId'] === null || row['partnerId'] === undefined ? '' : (row['partnerId'] as number));
    setAmount(row['carryoverAmount'] as number);
    setMode({ type: 'edit', row });
  }

  function done(text: string) {
    setMode(null);
    notify(text);
    reload();
  }

  function checkForm() {
    if (subjectId === '' || amount === '' || (mode?.type === 'create' && year === '')) {
      throw new Error('계정과목과 이월 금액을 입력해 주세요.');
    }
  }

  async function submitCreate() {
    checkForm();
    await call('POST', '/account-carryovers', role, {
      fiscalYear: year,
      accountSubjectId: subjectId,
      partnerId: partnerId === '' ? null : partnerId,
      carryoverAmount: amount,
    });
    done('이월내역을 등록했습니다.');
  }

  async function submitEdit(row: Row) {
    checkForm();
    await call('PUT', '/account-carryovers/' + String(row['accountCarryoverId']), role, {
      accountSubjectId: subjectId,
      partnerId: partnerId === '' ? null : partnerId,
      carryoverAmount: amount,
    });
    done('이월내역을 수정했습니다.');
  }

  async function submitDelete(row: Row) {
    await call('DELETE', '/account-carryovers/' + String(row['accountCarryoverId']), role);
    done('이월내역을 삭제했습니다.');
  }

  async function submitClose(row: Row) {
    await call('POST', '/account-carryovers/' + String(row['accountCarryoverId']) + '/close', role, {});
    done('이월내역을 마감했습니다.');
  }

  async function submitCancel(row: Row) {
    await call('POST', '/account-carryovers/' + String(row['accountCarryoverId']) + '/cancel-close', role, {});
    done('이월내역 마감을 취소했습니다.');
  }

  const columns = [
    {
      key: 'accountSubjectId',
      label: '계정과목',
      render: (r: Row) => <RefName table='account_subject' role={role} value={r['accountSubjectId']} />,
    },
    {
      key: 'partnerId',
      label: '거래처',
      render: (r: Row) =>
        r['partnerId'] === null || r['partnerId'] === undefined ? (
          <span>-</span>
        ) : (
          <RefName table='partner' role={role} value={r['partnerId']} />
        ),
    },
    { key: 'carryoverAmount', label: '이월 금액', render: (r: Row) => <Num value={r['carryoverAmount']} /> },
    { key: 'closingStatus', label: '마감 여부', render: (r: Row) => <Badge value={r['closingStatus']} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) =>
        r['closingStatus'] === '미마감' ? (
          <span>
            <button className='ghost' onClick={() => openEdit(r)}>수정</button>
            <button className='ghost' onClick={() => setMode({ type: 'delete', row: r })}>삭제</button>
            <button className='ghost' onClick={() => setMode({ type: 'close', row: r })}>마감</button>
          </span>
        ) : r['closingStatus'] === '마감' ? (
          <button className='ghost' onClick={() => setMode({ type: 'cancel', row: r })}>마감 취소</button>
        ) : (
          <span>-</span>
        ),
    },
  ];

  const formFields = (
    <>
      <Field label='계정과목' required>
        <LookupSelect table='account_subject' role={role} value={subjectId} onChange={setSubjectId} />
      </Field>
      <Field label='거래처'>
        <LookupSelect table='partner' role={role} value={partnerId} onChange={setPartnerId} placeholder='선택 안 함' />
      </Field>
      <Field label='이월 금액' required>
        <NumberInput value={amount} onChange={setAmount} />
      </Field>
    </>
  );

  return (
    <div>
      <h1>계정별 초기이월</h1>
      <Filters
        onSearch={() => {
          setPage(0);
          setYear(yearInput);
        }}
        onReset={() => {
          setYearInput(thisYear);
          setYear(thisYear);
          setPage(0);
        }}
      >
        <Field label='회계연도'>
          <NumberInput value={yearInput} onChange={setYearInput} />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={openCreate}>이월내역 등록</button>
      </Band>
      {error ? <ErrorText text={error} /> : null}
      <DataTable
        columns={columns}
        rows={data?.items ?? []}
        empty={loading ? '불러오는 중입니다.' : '아직 등록한 이월내역이 없습니다. 이월내역 등록 버튼으로 첫 내역을 추가해 주세요.'}
      />
      <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />

      {mode?.type === 'create' ? (
        <Drawer title='이월내역 등록' onClose={() => setMode(null)}>
          <Form onSubmit={submitCreate} submit='등록' note={'회계연도 ' + String(year) + '년 기준으로 등록합니다.'}>
            {formFields}
          </Form>
        </Drawer>
      ) : null}
      {mode?.type === 'edit' ? (
        <Drawer title='이월내역 수정' onClose={() => setMode(null)}>
          <Form onSubmit={() => submitEdit(mode.row)} submit='저장'>
            {formFields}
          </Form>
        </Drawer>
      ) : null}
      {mode?.type === 'delete' ? (
        <Drawer title='이월내역 삭제' onClose={() => setMode(null)}>
          <Form onSubmit={() => submitDelete(mode.row)} submit='삭제' danger note='삭제한 이월내역은 되돌릴 수 없습니다.' />
        </Drawer>
      ) : null}
      {mode?.type === 'close' ? (
        <Drawer title='이월내역 마감' onClose={() => setMode(null)}>
          <Form
            onSubmit={() => submitClose(mode.row)}
            submit='마감'
            note='마감하면 마감을 취소하기 전에는 수정하거나 삭제할 수 없습니다.'
          />
        </Drawer>
      ) : null}
      {mode?.type === 'cancel' ? (
        <Drawer title='마감 취소' onClose={() => setMode(null)}>
          <Form
            onSubmit={() => submitCancel(mode.row)}
            submit='마감 취소'
            note='마감을 취소하면 이월내역을 다시 수정할 수 있습니다.'
          />
        </Drawer>
      ) : null}
    </div>
  );
}
